// 설명을 위해 추가한 예제입니다. 원본 15개 CHECK에는 포함되지 않습니다.
bool TrySpend(int amount, int& gold) {
    if (amount < 0 || gold < 0 || amount > gold) {
        return false;  // 아직 gold를 바꾸지 않았습니다.
    }
    gold -= amount;    // 검사를 통과했으므로 결과는 0 이상입니다.
    return true;
}

